H = os.environ.get('LMK_HOME', '/Volumes/QIPU-SSD/qipu-render-work/combo/vancouver/lmk')   # patches / jobs / out live on the SSD, not in git
def cv(b, m=300, mn=2048):
    x0, y0, x1, y1 = b; x0 -= m; y0 -= m; x1 += m; y1 += m
    w, h = max(mn, x1 - x0), max(mn, y1 - y0); cx, cy = (x0 + x1) // 2, (y0 + y1) // 2
    return [cx - w // 2, cy - h // 2, cx - w // 2 + w, cy - h // 2 + h]
J = {}
def add(n, box, subject, mn=2048, **k): J[n] = dict(canvas=cv(box, mn=mn), subject=subject, **k)
